(2743775, 379585, 6519, '<td valign="top">My pick of the bunch. It fits the challenge, and I love the composition. The crooked horizon, however, bothers me.</td>', 'My pick of the bunch. It fits the challenge, and I love the composition. The crooked horizon, however, bothers me.', '2006-08-20 15:55:42.000000', NULL, 1),
