(2743923, 379585, 61138, '<td valign="top">Gorgeous image. Love the DOF. The composition and balance are just right, especially the placement and pose of the model. I give it a 10.</td>', 'Gorgeous image. Love the DOF. The composition and balance are just right, especially the placement and pose of the model. I give it a 10.', '2006-08-20 17:46:02.000000', NULL, 1),
(2744037, 379036, 48890, '<td valign="top">This picture stands out from the rest of the stuff in this challenge (I barely made myself to finish voting).  If not for the two people, standing over the bath tub, this would have been a fairly ordinary sample of an amaturely staged image, approaching the topic of the challenge in a boringly straightforward manner.  With the two sets of legs, however, this image gains some intrigue, a taste of some out-of-the-ordinary life (which may be full of vanity, but still, a welcome taste of something else). 9</td>', 'This picture stands out from the rest of the stuff in this challenge (I barely made myself to finish voting).  If not for the two people, standing over the bath tub, this would have been a fairly ordinary sample of an amaturely staged image, approaching the topic of the challenge in a boringly straightforward manner.  With the two sets of legs, however, this image gains some intrigue, a taste of some out-of-the-ordinary life (which may be full of vanity, but still, a welcome taste of something else). 9', '2006-08-20 18:25:56.000000', NULL, 1),
(2744116, 378452, 53878, '<td valign="top">white lighters are bad luck..</td>', 'white lighters are bad luck..', '2006-08-20 18:59:22.000000', NULL, 1),
