(2797542, 378452, 37858, '<td valign="top">Congrats on the 10th place finish.  The lighting is superb.  It makes the act of smoking an intimate experience...which works really well with the topic.  I don''t see how anyone could vote this a 1, 2, or 3 (unless they are smokers and think this is DNMC).  Obvously the majority thinks your image is right on...as I do.</td>', 'Congrats on the 10th place finish.  The lighting is superb.  It makes the act of smoking an intimate experience...which works really well with the topic.  I don''t see how anyone could vote this a 1, 2, or 3 (unless they are smokers and think this is DNMC).  Obvously the majority thinks your image is right on...as I do.', '2006-09-04 18:35:49.000000', NULL, 0),
(2797706, 380550, 51269, '<td valign="top">well, take the figure out &amp; I love it ! Guess you don''t "do" stupid, which is a good thing</td>', 'well, take the figure out & I love it ! Guess you don''t "do" stupid, which is a good thing', '2006-09-04 19:21:38.000000', NULL, 0),
(2797943, 381025, 53316, '<td valign="top">This is such an adorable shot!!  I love the concept and I really like the colors and composition. It''s so neat how the blue is reflecting in the toaster, bringing your composition some extra impact. I think that it has a bit of an overprocessed look to it, as the background looks very flat and the bears head looks very sharpened. I might not be explaining things well but I want to at least try to put into words what I would have noticed if I had voted in this challenge.  When I look at it now though all I can think of is OH HOW CUTE!!</td>', 'This is such an adorable shot!!  I love the concept and I really like the colors and composition. It''s so neat how the blue is reflecting in the toaster, bringing your composition some extra impact. I think that it has a bit of an overprocessed look to it, as the background looks very flat and the bears head looks very sharpened. I might not be explaining things well but I want to at least try to put into words what I would have noticed if I had voted in this challenge.  When I look at it now though all I can think of is OH HOW CUTE!!', '2006-09-04 20:33:20.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2828242, 379036, 52301, '<td valign="top">Please learn how to speak correctly, before leaving dumb comments. Thank you.</td>', 'Please learn how to speak correctly, before leaving dumb comments. Thank you.', '2006-09-12 16:23:16.000000', NULL, 0),
(2837915, 380912, 57882, '<td valign="top">I like this.  It''s so real.  The eyes are uniformely piercing, in a somewhat chaotic way.  Lighting is perfect and the composition is great.  Don''t think I would change anything about it.  Did you tell the kids what face to make?  They each did something different.  Very cool.</td>', 'I like this.  It''s so real.  The eyes are uniformely piercing, in a somewhat chaotic way.  Lighting is perfect and the composition is great.  Don''t think I would change anything about it.  Did you tell the kids what face to make?  They each did something different.  Very cool.', '2006-09-15 11:26:14.000000', NULL, 0),
(2841403, 379036, 26906, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by schthed:</b></div><hr/><i> Please learn how to speak correctly, before leaving dumb comments. Thank you. </i></td></tr></table> <br/> <br/>how adorable :)</td>', 'Originally posted by schthed: Please learn how to speak correctly, before leaving dumb comments. Thank you.   how adorable :)', '2006-09-16 22:08:40.000000', NULL, 0),
(2854051, 380912, 60862, '<td valign="top">Now THERE''S one for the family album!  My family tries to remember to take a few goofy shots at every occasion.  Picture 30 of us at my sister''s wedding, in tuxes and evening gowns, making funny faces. :)<br/> <br/>Maybe I''ll try this for the free study! LOL.</td>', 'Now THERE''S one for the family album!  My family tries to remember to take a few goofy shots at every occasion.  Picture 30 of us at my sister''s wedding, in tuxes and evening gowns, making funny faces. :) Maybe I''ll try this for the free study! LOL.', '2006-09-21 14:09:45.000000', NULL, 0),
(2903304, 381088, 60862, '<td valign="top">I regularly shake my head in dismay at the stupid things people do in the outdoors.  This reminds me of a couple I passed on my way off a mountain during a snowstorm.  My friend and I were fully dressed: long undies, sweater, parks, boots, and ice ax.  They were wearing jeans, a sweatshirt, and dock shoes.<br/> <br/>So I think you nailed it! :)</td>', 'I regularly shake my head in dismay at the stupid things people do in the outdoors.  This reminds me of a couple I passed on my way off a mountain during a snowstorm.  My friend and I were fully dressed: long undies, sweater, parks, boots, and ice ax.  They were wearing jeans, a sweatshirt, and dock shoes. So I think you nailed it! :)', '2006-10-06 14:52:09.000000', NULL, 0),
(2903464, 381088, 19708, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by levyj413:</b></div><hr/><i> I regularly shake my head in dismay at the stupid things people do in the outdoors.<br/>So I think you nailed it! :) </i></td></tr></table> <br/>Literally!<br/>That''s me, just a fool, playing it up a tad...<br/><img alt="'' . substr(''//img116.exs.cx/img116/1231/z7shysterical.gif'', strrpos(''//img116.exs.cx/img116/1231/z7shysterical.gif'', ''/'') + 1) . ''" border="0" src="//img116.exs.cx/img116/1231/z7shysterical.gif"/></td>', 'Originally posted by levyj413: I regularly shake my head in dismay at the stupid things people do in the outdoors.So I think you nailed it! :)  Literally!That''s me, just a fool, playing it up a tad...', '2006-10-06 15:40:25.000000', NULL, 0),
(2925848, 380912, 31403, '<td valign="top">five kids, and you have time to shoot?<br/> <br/>I have five also - but I have a wife who is very giving and lets me indulge my photography - she''s even MORE supportive when it makes money!<br/> <br/>Love this shot, and the peak inside your fun, frustrating, chaotic life!  God bless moms!</td>', 'five kids, and you have time to shoot? I have five also - but I have a wife who is very giving and lets me indulge my photography - she''s even MORE supportive when it makes money! Love this shot, and the peak inside your fun, frustrating, chaotic life!  God bless moms!', '2006-10-13 13:31:19.000000', NULL, 0),
(2965949, 378452, 53316, '<td valign="top"><i>This idea I hope does well as a serious subject amongst what I expect to be a bunch of silly shots.</i> <br/> <br/>You did that very well, congrats!</td>', 'This idea I hope does well as a serious subject amongst what I expect to be a bunch of silly shots.  You did that very well, congrats!', '2006-10-26 19:22:14.000000', NULL, 0),
(3040441, 381211, 62637, '<td valign="top">if i were to retake this shot (not that i want to get that close again!) i think id go barefoot, and use a larger aperture.  the background is fairly confusing, i think it would look better blurred out.</td>', 'if i were to retake this shot (not that i want to get that close again!) i think id go barefoot, and use a larger aperture.  the background is fairly confusing, i think it would look better blurred out.', '2006-11-17 14:56:32.000000', NULL, 0),
(3103368, 381211, 69008, '<td valign="top">Scary looking spot. You live in a beautiful part of the world, but too cold for me.  I use a monopod when I hike around, and it allows me to get angles and places that I would not other wise be able to get. I would suggest that you may make good use of one as well. With the MP you could hold the camera right out over the edge of the fall using the self timer. They  also make a good walking stick while hiking up and down rough terrain, and allow you to get a shot from a high angle in crowds or over an obsticle like a short tree blocking a great view. <br/>I like the pic just the way you shot it, with everything in focus, as the sharpness of the bottom of the gorge increases the feeling of great distance to the bottom. Keep clickin''</td>', 'Scary looking spot. You live in a beautiful part of the world, but too cold for me.  I use a monopod when I hike around, and it allows me to get angles and places that I would not other wise be able to get. I would suggest that you may make good use of one as well. With the MP you could hold the camera right out over the edge of the fall using the self timer. They  also make a good walking stick while hiking up and down rough terrain, and allow you to get a shot from a high angle in crowds or over an obsticle like a short tree blocking a great view. I like the pic just the way you shot it, with everything in focus, as the sharpness of the bottom of the gorge increases the feeling of great distance to the bottom. Keep clickin''', '2006-12-10 00:31:43.000000', NULL, 0),
(3147389, 379778, 66709, '<td valign="top">This is an awesome shot.  It shows alot of details and I don''t see any tilt.<br/> <br/><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by lambie83:</b></div><hr/><i> It is stupid, but the picture is not great.  Sharper focus and fixing crooked horizon would have improved it. </i></td></tr></table></td>', 'This is an awesome shot.  It shows alot of details and I don''t see any tilt. Originally posted by lambie83: It is stupid, but the picture is not great.  Sharper focus and fixing crooked horizon would have improved it. ', '2006-12-25 05:33:22.000000', NULL, 0),
(3147884, 379889, 65886, '<td valign="top">good photo and a clever idea! very nice pp, too!</td>', 'good photo and a clever idea! very nice pp, too!', '2006-12-25 13:25:50.000000', NULL, 0),
(3181622, 380533, 48389, '<td valign="top">Hi Victor, excellent idea! Such a shame you didn''t get your original image in on time, at least you have learnt for the future! You seem to have got the hang of your depth of field and used it nicely here in this image. The image matches the challenge title nicely and had you submitted the original (and it been approved) I think this shot would have done very well :o)</td>', 'Hi Victor, excellent idea! Such a shame you didn''t get your original image in on time, at least you have learnt for the future! You seem to have got the hang of your depth of field and used it nicely here in this image. The image matches the challenge title nicely and had you submitted the original (and it been approved) I think this shot would have done very well :o)', '2007-01-04 16:34:44.000000', NULL, 0),
